<?php require_once __DIR__ . '/ResourceController.php'; final class PermissionController { public static function index(string $method, ?string $role = null): never { if ($method === 'GET' && $role === null) { RoleMiddleware::allow(['Super Admin']); Response::success('Request successful', MySQLRepository::permissions()); } if ($method === 'PUT' && $role !== null) { RoleMiddleware::allow(['Super Admin']); $data = Validation::body(); Validation::required($data, ['permissions']); if (!in_array($role, ['Super Admin', 'Admin'], true) || !is_array($data['permissions'])) Response::error('Invalid permission payload', 'INVALID_PERMISSIONS', 422); Response::success('Permissions updated', MySQLRepository::savePermissions($role, $data['permissions'])); } Response::error('Method not allowed', 'METHOD_NOT_ALLOWED', 405); } }
